const normalizedGlobalRepoAuditCommand =
    normalizeCasualGateText(comando);

const isExactGlobalRepoAuditCommand =
    /^(?:jarvis[\s,]+|heberto[\s,]+|gestia[\s,]+)?(?:analiza|analizar|audita|auditar|revisa|revisar)\s+(?:el\s+)?(?:repo|repositorio)$/.test(
        normalizedGlobalRepoAuditCommand
    );

if (isExactGlobalRepoAuditCommand) {
    console.info(
        "[TERMINAL_GLOBAL_REPO_AUDIT_41_44]",
        {
            command: comando,
            traceId: currentTraceId,
            writeAllowed: false
        }
    );

    let auditResult = null;

    if (window.ToolsBridge?.executeAndCompose) {
        auditResult =
            await window.ToolsBridge.executeAndCompose(
                "repo.audit",
                {},
                {
                    rawInput: comando,
                    analysisId: currentTraceId,
                    traceId: currentTraceId,
                    source: "terminal_global_repo_audit_41_44",
                    tenantId:
                        window.session?.tenantId ||
                        window.KernelHeberto?.session?.tenantId ||
                        "UXMAL39",
                    approved: false,
                    codexApproved: false
                }
            );
    }
    else if (window.JarvisToolRuntime?.execute) {
        auditResult =
            await window.JarvisToolRuntime.execute(
                "repo.audit",
                {},
                {
                    rawInput: comando,
                    analysisId: currentTraceId,
                    traceId: currentTraceId,
                    source: "terminal_global_repo_audit_41_44",
                    approved: false,
                    codexApproved: false
                }
            );
    }

    const auditPayloadCandidates =
        [
            auditResult,
            auditResult?.data,
            auditResult?.data?.data,
            auditResult?.response,
            auditResult?.response?.data,
            auditResult?.response?.data?.data,
            auditResult?.result,
            auditResult?.result?.data,
            auditResult?.result?.observations?.[0],
            auditResult?.result?.observations?.[0]?.response,
            auditResult?.result?.observations?.[0]?.response?.data
        ]
            .filter(Boolean);

    const auditPayload =
        auditPayloadCandidates.find(item =>
            Array.isArray(item?.files) ||
            Array.isArray(item?.modules) ||
            Number.isFinite(item?.totalFiles) ||
            Number.isFinite(item?.count)
        ) ||
        {};

    if (typeof window.rehydrateRepoCognitionIndex === "function") {
        window.rehydrateRepoCognitionIndex();
    }

    const structure =
        Array.isArray(auditPayload.files)
            ? auditPayload.files
            : Array.isArray(window.__FULL_REPO_STRUCTURE__)
                ? window.__FULL_REPO_STRUCTURE__
                : Object.keys(window.__REPO_INDEX__ || {});

    const normalizedFiles =
        structure
            .map(item =>
                typeof item === "string"
                    ? item
                    : item?.path || item?.file || item?.name || ""
            )
            .filter(Boolean);

    const cognitionEntries =
        Object.entries(window.__REPO_COGNITION__ || {});

    const graph =
        window.__REPO_DEP_GRAPH__ || {};

    const runtimeHealth =
        window.__RUNTIME_HEALTH_MAP__ || {};

    const moduleOwnership =
        window.__MODULE_OWNERSHIP__ || {};

    const moduleNames =
        new Set(
            [
                ...Object.keys(moduleOwnership),
                ...cognitionEntries.map(([, node]) => node?.module).filter(Boolean),
                ...(Array.isArray(auditPayload.modules)
                    ? auditPayload.modules.map(item =>
                        typeof item === "string"
                            ? item
                            : item?.name || item?.module || item?.id || ""
                    )
                    : [])
            ]
                .filter(Boolean)
        );

    const criticalNodes =
        cognitionEntries
            .filter(([, node]) =>
                node?.critical === true ||
                node?.cognition?.governance === "CRITICAL" ||
                Number(node?.cognition?.criticality || 0) >= 90
            );

    const highRiskNodes =
        cognitionEntries
            .filter(([, node]) =>
                node?.cognition?.riskLevel === "HIGH" ||
                Number(node?.cognition?.criticality || 0) >= 70
            );

    const graphMissing =
        cognitionEntries
            .filter(([file]) => !graph[file])
            .map(([file]) => file);

    const zeroDependencyCritical =
        criticalNodes
            .filter(([file]) =>
                Number(graph?.[file]?.totalDependencies || 0) === 0
            )
            .map(([file]) => file);

    const unhealthyRuntime =
        Object.entries(runtimeHealth)
            .filter(([, node]) =>
                node?.state && node.state !== "ONLINE" ||
                Number(node?.health ?? 100) < 90
            );

    const functionCount =
        Number(
            auditPayload.totalFunctions ||
            auditPayload.functionsCount ||
            auditPayload.functionCount ||
            0
        );

    const totalFiles =
        Number(
            auditPayload.totalFiles ||
            auditPayload.count ||
            normalizedFiles.length ||
            cognitionEntries.length
        );

    const extensionCounts =
        normalizedFiles.reduce((acc, file) => {
            const match = String(file).match(/\.([a-z0-9]+)$/i);
            const extension = match ? match[1].toLowerCase() : "sin_extension";
            acc[extension] = (acc[extension] || 0) + 1;
            return acc;
        }, {});

    const domainGroups =
        {
            jarvis: normalizedFiles.filter(file => /jarvis|gestia-core|brain|semantic|intent/i.test(file)),
            flotilla: normalizedFiles.filter(file => /flota|flotilla|vehicul|gps|visor-flota/i.test(file)),
            b2b: normalizedFiles.filter(file => /b2b|cmms|mantenimiento/i.test(file)),
            cliente: normalizedFiles.filter(file => /cliente/i.test(file)),
            tecnico: normalizedFiles.filter(file => /tecnico/i.test(file)),
            admin: normalizedFiles.filter(file => /admin|ceo/i.test(file)),
            firebase: normalizedFiles.filter(file => /firebase|firestore|storage|functions/i.test(file))
        };

    const findings = [];

    if (graphMissing.length) {
        findings.push(
            `- Mapa de dependencias incompleto: ${graphMissing.length} nodos cognitivos no tienen nodo en el grafo.`
        );
    }

    if (zeroDependencyCritical.length) {
        findings.push(
            `- Riesgo de falsa seguridad: ${zeroDependencyCritical.length} archivos críticos aparecen con 0 dependencias registradas.`
        );
    }

    if (unhealthyRuntime.length) {
        findings.push(
            `- Runtime degradado: ${unhealthyRuntime.length} módulos no están ONLINE o tienen salud menor a 90.`
        );
    }

    if (domainGroups.flotilla.length === 0) {
        findings.push(
            "- Flotilla: no se detectaron archivos claramente clasificados para este dominio; revisar registro e indexación del módulo."
        );
    }
    else {
        const flotillaGraphNodes =
            domainGroups.flotilla.filter(file => graph[file]);

        if (flotillaGraphNodes.length < domainGroups.flotilla.length) {
            findings.push(
                `- Flotilla: ${domainGroups.flotilla.length - flotillaGraphNodes.length} de ${domainGroups.flotilla.length} archivos no están conectados al grafo de dependencias.`
            );
        }
    }

    if (!findings.length) {
        findings.push(
            "- No se detectaron inconsistencias estructurales obvias con los índices disponibles. Falta análisis semántico por dominio para validar flujos funcionales."
        );
    }

    const topCritical =
        criticalNodes
            .slice(0, 12)
            .map(([file, node]) =>
                `- ${file} | módulo ${node?.module || "ND"} | criticidad ${node?.cognition?.criticality ?? "ND"}`
            );

    const report =
        [
            "ANÁLISIS GLOBAL DEL REPOSITORIO SIA7",
            "",
            "Inventario:",
            `- Archivos detectados: ${totalFiles}`,
            `- Módulos detectados: ${moduleNames.size}`,
            `- Funciones detectadas: ${functionCount || "ND (el índice actual no entrega conteo global confiable)"}`,
            `- Nodos cognitivos: ${cognitionEntries.length}`,
            `- Nodos del grafo: ${Object.keys(graph).length}`,
            `- Archivos críticos: ${criticalNodes.length}`,
            `- Archivos de riesgo alto: ${highRiskNodes.length}`,
            "",
            "Distribución por tipo:",
            ...Object.entries(extensionCounts)
                .sort((a, b) => b[1] - a[1])
                .slice(0, 10)
                .map(([extension, count]) => `- .${extension}: ${count}`),
            "",
            "Cobertura por dominio:",
            `- Cerebro/Jarvis: ${domainGroups.jarvis.length} archivos`,
            `- Flotilla: ${domainGroups.flotilla.length} archivos`,
            `- B2B/CMMS: ${domainGroups.b2b.length} archivos`,
            `- Cliente: ${domainGroups.cliente.length} archivos`,
            `- Técnico: ${domainGroups.tecnico.length} archivos`,
            `- Admin/CEO: ${domainGroups.admin.length} archivos`,
            `- Firebase/Functions: ${domainGroups.firebase.length} archivos`,
            "",
            "Hallazgos estructurales:",
            ...findings,
            "",
            "Nodos críticos prioritarios:",
            ...(topCritical.length ? topCritical : ["- ND"]),
            "",
            "Prioridad recomendada:",
            "1. Completar el grafo real de dependencias antes de confiar en riesgo LOW o impacto 0.",
            "2. Auditar por dominio empezando por cerebro/Jarvis, flotilla y B2B.",
            "3. Validar flujos de negocio contra estados reales, no solo coincidencias de texto.",
            "4. Mantener todo en lectura; no se generó patch ni escritura."
        ]
            .join("\n");

    window.renderJarvisResponse?.(
        "Análisis global SIA7",
        report,
        findings.some(item => /incompleto|riesgo|degradado|no están conectados/i.test(item))
            ? "warning"
            : "success"
    );

    handled = true;
    return;
}

if (
    window.GestiaCore?.procesarIntencion &&
    !["arre", "confirmar", "ok"].includes(cmd)
) {
